
// ══ BUILD 4.1 — brand assets ══
var SC_BRAND={name:'NQAS | FAST',nameHTML:'NQAS<i>|</i>FAST',by:'HealSol Academy',logoNqas:'data:image/jpeg;base64,',logoMark:'data:image/jpeg;base64,',logoHealsol:'data:image/png;base64,'};
(function(){
  // the language class lets Hindi get its own line spacing
  function syncLang(){ try{ document.body.classList.toggle('lang-hi',_appLang==='hi'); }catch(e){} }
  var oSet=typeof setLang==='function'?setLang:null;
  if(oSet) setLang=function(){ var r=oSet.apply(this,arguments); syncLang(); return r; };
  // brand marks replace the old "H" boxes
  function brand(){
    var mk='<img class="nf-mark" alt="NQAS.QI" src="'+SC_BRAND.logoMark+'">';
    [['.login-icon',''],['.admin-nav-icon',''],['.cho-nav-icon','']].forEach(function(p){ document.querySelectorAll(p[0]).forEach(function(el){
      if(el.dataset.nf) return; el.dataset.nf='1'; el.innerHTML=mk; el.style.background='transparent'; el.style.width='auto'; el.style.height='auto'; el.style.padding='0'; el.style.boxShadow='none'; }); });
  }
  if(document.readyState!=='loading'){ brand(); syncLang(); } else document.addEventListener('DOMContentLoaded',function(){ brand(); syncLang(); });
})();
